tools.example:
mdl = 'archDemo';
new_system(mdl); open_system(mdl);
add_block('simulink/Ports & Subsystems/Subsystem', [mdl '/Ctrl']);
set_param([mdl '/Ctrl'], 'TreatAsAtomicUnit', 'on', ...
    'SystemSampleTime', '0.01', 'RTWSystemCode', 'Reusable function');
% a new Subsystem is pre-populated with In1 -> Out1; add blocks inside it
add_block('simulink/Math Operations/Gain', [mdl '/Ctrl/K']);
set_param([mdl '/Ctrl/K'], 'Gain', '2.5');

add_block('simulink/Ports & Subsystems/Enabled Subsystem', [mdl '/EnaSub']);
set_param([mdl '/EnaSub/Enable'], 'StatesWhenEnabling', 'reset', 'ShowOutputPort', 'on');
set_param([mdl '/EnaSub/Out1'], 'OutputWhenDisabled', 'held', 'InitialOutput', '0');

add_block('simulink/Ports & Subsystems/Function-Call Subsystem', [mdl '/FcnSub']);
set_param([mdl '/FcnSub/Trigger'], 'TriggerType', 'function-call', ...
    'SampleTimeType', 'periodic', 'StatesWhenEnabling', 'held');
add_block('simulink/Ports & Subsystems/Function-Call Generator', [mdl '/FCG']);
set_param([mdl '/FCG'], 'sample_time', '0.01');
add_line(mdl, 'FCG/1', 'FcnSub/1', 'autorouting', 'on');

add_block('simulink/Ports & Subsystems/If', [mdl '/If']);
set_param([mdl '/If'], 'NumInputs', '2', ...
    'IfExpression', 'u1 > 0', ...
    'ElseIfExpressions', 'u1 < 0', 'ShowElse', 'on');

add_block('simulink/Ports & Subsystems/If Action Subsystem', [mdl '/ThenBranch']);
add_block('simulink/Ports & Subsystems/If Action Subsystem', [mdl '/ElseBranch']);
add_line(mdl, 'If/1', 'ThenBranch/1', 'autorouting', 'on');   % action port
add_line(mdl, 'If/2', 'ElseBranch/1', 'autorouting', 'on');
set_param([mdl '/ThenBranch/Action Port'], 'InitializeStates', 'held');

add_block('simulink/Ports & Subsystems/Switch Case', [mdl '/Case']);
set_param([mdl '/Case'], 'CaseConditions', '{1, [2 3], 4}', 'ShowDefaultCase', 'on');
add_block('simulink/Ports & Subsystems/Switch Case Action Subsystem', [mdl '/Mode1']);
add_line(mdl, 'Case/1', 'Mode1/1', 'autorouting', 'on');

add_block('simulink/Ports & Subsystems/For Iterator Subsystem', [mdl '/ForSub']);
set_param([mdl '/ForSub/For Iterator'], 'IterationSource', 'internal', ...
    'IterationLimit', '10', 'ShowIterationPort', 'on', ...
    'IndexMode', 'One-based', 'ResetStates', 'held');

add_block('simulink/Ports & Subsystems/For Each Subsystem', [mdl '/EachSub']);
set_param([mdl '/EachSub/For Each'], 'InputPartition', 'on', ...
    'PartitionDimension', '1', 'PartitionWidth', '1', ...
    'OutputConcatenation', 'on', 'ConcatenationDimension', '1');

add_block('simulink/Ports & Subsystems/While Iterator Subsystem', [mdl '/WhileSub']);
set_param([mdl '/WhileSub/While Iterator'], 'WhileBlockType', 'do-while', ...
    'MaxIters', '100', 'ShowIterationPort', 'on', 'ResetStates', 'held');

add_block('simulink/Ports & Subsystems/Model', [mdl '/Plant']);
set_param([mdl '/Plant'], 'ModelNameDialog', 'plantModel.slx', ...
    'SimulationMode', 'Accelerator');
ip = get_param([mdl '/Plant'], 'InstanceParameters');
ip(1).Value = '3.5';
set_param([mdl '/Plant'], 'InstanceParameters', ip);

add_block('simulink/Ports & Subsystems/Variant Subsystem', [mdl '/Plant']);
set_param([mdl '/Plant'], 'VariantControlMode', 'label', ...
    'VariantActivationTime', 'update diagram');
% add two choices inside, then pick one
set_param([mdl '/Plant'], 'LabelModeActiveChoice', 'HighFidelity');

add_block('simulink/Signal Routing/Variant Source', [mdl '/VSrc']);
set_param([mdl '/VSrc'], 'VariantControlMode', 'sim codegen switching', ...
    'ShowConditionOnBlock', 'on');

% create the reusable subsystem file once
new_system('timesK', 'Subsystem');
save_system('timesK');
% instantiate it twice in a model
add_block('simulink/Ports & Subsystems/Subsystem Reference', [mdl '/K1']);
set_param([mdl '/K1'], 'ReferencedSubsystem', 'timesK');
add_block([mdl '/K1'], [mdl '/K2']);

add_block('simulink/User-Defined Functions/MATLAB Function', [mdl '/Algo']);
code = sprintf('function y = fcn(u, k)\n%%#codegen\ny = k * tanh(u);\nend');
rt = sfroot;
ch = rt.find('-isa', 'Stateflow.EMChart', 'Path', [mdl '/Algo']);
ch.Script = code;
set_param(mdl, 'SimulationCommand', 'update');   % rebuild ports from the signature

add_block('simulink/User-Defined Functions/MATLAB System', [mdl '/Sys']);
set_param([mdl '/Sys'], 'System', 'myPkg.MyFilter', ...
    'SimulateUsing', 'Code generation');

add_block('simulink/User-Defined Functions/Simulink Function', [mdl '/computeLimit']);
% the prototype y = computeLimit(u) is edited on the block icon;
% the body uses Argument Inport / Argument Outport blocks inside
add_block('simulink/User-Defined Functions/Function Caller', [mdl '/callLimit']);
set_param([mdl '/callLimit'], 'FunctionPrototype', 'y = computeLimit(u)');

add_block('simulink/User-Defined Functions/Function Caller', [mdl '/callLimit']);
set_param([mdl '/callLimit'], 'FunctionPrototype', 'y = computeLimit(u)', ...
    'InputArgumentSpecifications', 'single(1)', ...
    'OutputArgumentSpecifications', 'single(1)', 'SampleTime', '0.01');

% register the external code on the model first
set_param(mdl, 'SimUserSources', 'my_alg.c', 'SimUserIncludeDirs', '.');
set_param(mdl, 'CustomHeaderCode', '#include "my_alg.h"');
add_block('simulink/User-Defined Functions/C Caller', [mdl '/callC']);
set_param([mdl '/callC'], 'FunctionName', 'saturate_i16');
funcs = get_param([mdl '/callC'], 'AvailableFunctions');

blk = [mdl '/Ctrl'];
m = Simulink.Mask.create(blk);
m.Type = 'PI Controller';
m.Description = 'Discrete PI controller with anti-windup.';
m.addParameter('Type', 'edit',  'Name', 'Kp', 'Prompt', 'Proportional gain', 'Value', '1');
m.addParameter('Type', 'edit',  'Name', 'Ki', 'Prompt', 'Integral gain',     'Value', '0.1');
m.addParameter('Type', 'popup', 'Name', 'mode', 'Prompt', 'Mode', ...
    'TypeOptions', {'Discrete','Continuous'}, 'Value', 'Discrete');
m.Display = 'disp(''PI'')';
% read it back later
m2 = Simulink.Mask.get(blk);
kp = m2.getParameter('Kp').Value;

load_system(mdl);
blks = find_system(mdl, 'SearchDepth', 1, 'BlockType', 'Gain');
h = get_param(blks, 'Handle');
Simulink.BlockDiagram.createSubsystem(cell2mat(h), ...
    'Name', 'GainStage', 'MakeNameUnique', 'on');
set_param([mdl '/GainStage'], 'TreatAsAtomicUnit', 'on');

load_system(mdl);
ok = Simulink.SubSystem.convertToModelReference([mdl '/Ctrl'], 'ctrlModel', ...
    'AutoFix', true, 'ReplaceSubsystem', true, ...
    'BuildTarget', 'Sim', 'CheckSimulationResults', true);
if ok
    set_param([mdl '/Ctrl'], 'SimulationMode', 'Accelerator');
end

load_system(mdl);
libdata = libinfo(mdl);
for k = 1:numel(libdata)
    fprintf('%-40s <- %s (%s)\n', libdata(k).Block, ...
        libdata(k).ReferenceBlock, libdata(k).LinkStatus);
end
% break the link on one block so it can be edited independently
set_param(libdata(1).Block, 'LinkStatus', 'none');
% or disable it temporarily and restore it later
set_param(libdata(2).Block, 'LinkStatus', 'inactive');
set_param(libdata(2).Block, 'LinkStatus', 'restore');
